"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/blog-sections/variants/01-image-cards";
import Variant1 from "./components/blog-sections/variants/02-featured-stories";
import Variant2 from "./components/blog-sections/variants/03-article-list";
import Variant3 from "./components/blog-sections/variants/04-article-cards";
const variants = {"image-cards": Variant0,"featured-stories": Variant1,"article-list": Variant2,"article-cards": Variant3};
export interface ArtemisBlogSectionsProps { className?: string; variant?: "image-cards" | "featured-stories" | "article-list" | "article-cards"; }
export function ArtemisBlogSections({ className, variant = "image-cards" }: ArtemisBlogSectionsProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }
